using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEngine.Profiling;
internal class CommandScript:IRunCommand{
 const string R="C:/Users/15352/Documents/Codex/2026-10-27/task-2/render-fix21/continuous47-counts/";
 [Serializable]class Row{public string gid,type,name,hierarchy,json;public bool dirty;}
 [Serializable]class State{public string utc,scenePath;public bool sceneDirty,playing,paused,compiling,background;public float timeScale,captureDelta;public string[]dirtyAssets,rootIDs;public int rtCount;public long allocated,rtBytes;}
 static string ID(UnityEngine.Object o)=>o?GlobalObjectId.GetGlobalObjectIdSlow(o).ToString():"null";
 static string PathOf(Transform t){string p=t.name;while(t.parent){t=t.parent;p=t.name+"/"+p;}return p;}
 public void Execute(ExecutionResult r){if(EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling)throw new Exception("Stable Edit required for final read");var s=SceneManager.GetActiveScene();if(s.path!="Assets/Scenes/GameMap1.unity")throw new Exception("Other scene; preserve it");var rt=Resources.FindObjectsOfTypeAll<RenderTexture>();var state=new State{utc=DateTime.UtcNow.ToString("O"),scenePath=s.path,sceneDirty=s.isDirty,playing=EditorApplication.isPlaying,paused=EditorApplication.isPaused,compiling=EditorApplication.isCompiling,timeScale=Time.timeScale,captureDelta=Time.captureDeltaTime,background=Application.runInBackground,rootIDs=s.GetRootGameObjects().Select(ID).ToArray(),dirtyAssets=Resources.FindObjectsOfTypeAll<UnityEngine.Object>().Where(o=>o&&EditorUtility.IsPersistent(o)&&EditorUtility.IsDirty(o)).Select(AssetDatabase.GetAssetPath).Where(p=>!string.IsNullOrEmpty(p)&&(p.StartsWith("Assets/")||p.StartsWith("ProjectSettings/"))).Distinct().OrderBy(p=>p).ToArray(),allocated=Profiler.GetTotalAllocatedMemoryLong(),rtBytes=rt.Sum(t=>Profiler.GetRuntimeMemorySizeLong(t)),rtCount=rt.Length};File.WriteAllText(R+"FINAL_STATE.json",JsonUtility.ToJson(state,true));using(var f=new StreamWriter(R+"SCENE_AFTER.ndjson")){foreach(var t in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)))foreach(var o in new UnityEngine.Object[]{t.gameObject}.Concat(t.GetComponents<Component>().Cast<UnityEngine.Object>()))if(o)f.WriteLine(JsonUtility.ToJson(new Row{gid=ID(o),type=o.GetType().FullName,name=o.name,hierarchy=PathOf(t),json=EditorJsonUtility.ToJson(o),dirty=EditorUtility.IsDirty(o)}));}r.Log("Final Edit read sceneDirty="+state.sceneDirty+" dirtyAssets="+state.dirtyAssets.Length+" RT="+state.rtCount+" RTbytes="+state.rtBytes+" allocated="+state.allocated+"; no state modified.");}
}

